/bin/bash -lc "node --input-type=module <<'JS'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import assert from 'node:assert/strict';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], { detached: true, env: { ...process.env, PORT: '18080', DB_PATH: join(directory, 'db.sqlite') }, stdio: ['ignore', 'pipe', 'pipe'] });
try {
  await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('Startup timeout')), 10000);
    child.stdout.on('data', (chunk) => {
      if (String(chunk).includes('Workboard listening')) { clearTimeout(timer); resolve(); }
    });
    child.once('error', (error) => { clearTimeout(timer); reject(error); });
  });
  const response = await fetch('http://127.0.0.1:18080/health');
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: 'ok' });
  assert.equal((await fetch('http://127.0.0.1:18080/')).status, 200);
  console.log('npm start launch and health smoke check passed');
} finally {
  const exited = new Promise(resolve => child.once('exit', resolve));
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, { recursive: true, force: true });
}
JS"

